// Run this Playwright function in a separate ComfyUI browser page.
// Replace __H3_MODULAR_SPECS__ with the JSON generated by build_h3_modular_spec.py.
// Returns artifacts to the caller; the browser never writes workflow files itself.
async (page) => {
  const specs = __H3_MODULAR_SPECS__;
  const p = page.context().browser().contexts().flatMap(c => c.pages())
    .find(p => p.url().startsWith('http://127.0.0.1:8188/'));
  if (!p) throw new Error('Open an isolated ComfyUI page before building.');
  const results = [];
  for (const spec of specs) {
    const result = await p.evaluate(async spec => {
      const app = window.comfyAPI.app.app;
      app.graph.clear();
      const g = app.graph, built = {}, counts = {};
      const setValue = async (n, name, value) => {
        const w = n.widgets?.find(w => w.name === name);
        if (!w) throw new Error(`${n.type}: widget ${name} not found`);
        w.value = value;
        if (w.callback) await w.callback(value, app.canvas, n, [], {});
      };
      for (const item of spec.nodes) {
        const n = LiteGraph.createNode(item.type);
        if (!n) throw new Error(`Missing node ${item.type}`);
        g.add(n); built[item.key] = n;
        if (item.preset) {
          // Preserve the known installed-model preset by widget name/order.
          for (let i = 0; i < item.preset.length; i++) {
            const w = n.widgets?.[i];
            if (w) await setValue(n, w.name, item.preset[i]);
          }
        }
        for (const [name, value] of Object.entries(item.values)) {
          if (!Array.isArray(value)) await setValue(n, name, value);
        }
        n.title = item.title;
        n.properties.h3_modular_key = item.key;
        if (item.key === 'previous_media') n.properties.ytonMediaCollapsed = {image:true,video:false,audio:true};
        if (item.outputType) n.outputs[0].type = item.outputType;
        // Fixed seeds are essential for comparing modules.
        for (const w of n.widgets ?? []) if (w.name === 'control_after_generate') w.value = 'fixed';
        const index = counts[item.module] ?? 0;
        counts[item.module] = index + 1;
        n.pos = [(index % 4) * 440, Math.floor(index / 4) * 760];
        n.size = [390, Math.max(n.computeSize()[1], 110)];
      }
      const socketLabels = {
        target_width:['目标宽度'],target_height:['目标高度'],duration:['成片秒数'],seed:['种子'],two_pass:['二采开关'],
        enable_context:['上下文开关'],replica_mode:['复刻模式'],enable_face:['修脸开关'],enable_color:['调色开关'],clip_index:['片段序号'],
        models:['基础模型','CLIP','视频 VAE','音频 VAE'],main_model:['首采模型'],second_model:['二采精修模型'],
        media:['参考图片','参考视频','参考音频'],previous_media:['上段图片','上段视频','上段音频'],
        first_video:['首个源视频'],first_previous:['上一段成片'],no_previous:['无上一段'],no_source:['无源视频'],
        has_context:['接续生效'],overlap:['上下文帧数'],normal_plan:['总帧数','头裁切','尾裁切','源起点','可见帧数'],
        replica_plan:['复刻帧数','复刻头裁切','复刻尾裁切'],length:['总帧数'],head:['头裁切帧数'],tail:['尾裁切帧数'],
        low_w:['首采宽度'],low_h:['首采高度'],safe_video:['参考视频'],source_range:['源片段画面'],
        context_last:['上段尾帧'],context_batch:['上段引导 22 帧'],previous_tail:['上段尾部画面','上段尾部音频'],
        use_source_guide:['源画面引导开关'],reference_select:['首采条件'],reference:['参考条件','首采 latent'],
        main_sample:['首采结果','首采干净 latent'],high_schedule:['二采 Sigma'],high_random:['二采噪声'],high_noise:['二采噪声'],
        high_av:['二采 latent'],upscale_film:['二采 latent'],high_guider:['二采 Guider'],final_latent:['最终 latent'],
        decode:['原始成片画面'],face_select:['成片画面'],video:['本段视频'],prompt:['提示词']
      };
      for (const item of spec.nodes) {
        const n = built[item.key];
        for (const [name, value] of Object.entries(item.values)) {
          if (!Array.isArray(value)) continue;
          let slot = name.startsWith('#') ? Number(name.slice(1)) : n.findInputSlot(name);
          if (slot < 0) {
            const w = n.widgets?.find(w => w.name === name);
            if (!w) throw new Error(`${item.key}: missing input ${name}`);
            n.convertWidgetToInput(w);
            slot = n.findInputSlot(name);
          }
          const source = built[value[0]];
          if (!source.connect(value[1], n, slot)) throw new Error(`Cannot connect ${value} -> ${item.key}.${name}`);
          // Re-read the slot after connect: autogrow nodes may change their slot order.
          slot = name.startsWith('#') ? Number(name.slice(1)) : n.findInputSlot(name);
          const label = socketLabels[value[0]]?.[value[1]] ?? source.title;
          if (slot >= 0) n.inputs[slot].label = label;
          source.outputs[value[1]].label = label;
        }
      }
      // Save a fully expanded graph too, so every individual connection is inspectable.
      const flat = g.serialize();
      const moduleNodes = {};
      for (const [key, members] of Object.entries(spec.modules)) {
        const converted = g._convertToSubgraphImpl(new Set(members.map(id => built[id])));
        converted.subgraph.name = spec.names[key];
        converted.node.title = spec.names[key];
        moduleNodes[key] = converted.node;
        if (key === 'params') {
          // Native input-to-widget promotion makes the controls editable on the main canvas.
          for (const item of spec.nodes.filter(x => x.module === key && x.type.startsWith('Primitive'))) {
            const inner = converted.subgraph.nodes.find(n => n.properties.h3_modular_key === item.key);
            const port = converted.subgraph.addInput(item.title, inner.outputs[0].type);
            port.connect(inner.inputs[inner.findInputSlot('value')], inner);
          }
        }
        // Use compact rows with enough room for tall node panels.
        let rowY=100;
        const innerNodes=converted.subgraph.nodes;
        for (let start=0;start<innerNodes.length;start+=3) {
          const row=innerNodes.slice(start,start+3);
          row.forEach((n,i)=>{n.pos=[100+i*500,rowY];});
          rowY+=Math.max(...row.map(n=>n.size[1]))+150;
        }
        if (key==='high') {
          const layout={
            high_reference:[100,100],high_reference_source:[600,100],high_reference_source_select:[1100,100],
            high_reference_context:[600,500],high_reference_feather:[1100,500],high_reference_select:[1600,100],
            high_guider:[2100,100],high_schedule:[100,950],high_random:[100,1200],separate:[600,950],
            upscale_3d:[1100,950],high_av:[1600,950],upscale_film:[1100,950],high_noise:[1600,950]
          };
          for (const n of innerNodes) n.pos=layout[n.properties.h3_modular_key];
        }
        // Give cross-module sockets meaningful names instead of repeated INT / LATENT.
        for (const input of converted.node.inputs) {
          const port = converted.subgraph.inputs.find(x => x.id === input._subgraphSlotId);
          if (port) input.label = port.label ?? port.name;
        }
      }
      const positions = {
        params:[40,80], models:[40,580], plan:[500,80], source:[500,590], context:[500,990],
        reference:[960,80], main:[1420,80], high:[1420,590], second:[1880,80], face:[2340,80], output:[2800,80]
      };
      for (const [key, n] of Object.entries(moduleNodes)) {
        n.pos = positions[key];
        n.size = [370, Math.max(180, n.computeSize()[1])];
        n.color = key === 'high' ? '#294c5c' : '#303e4a';
        n.bgcolor = '#202b34';
      }
      built.media.pos = [40,1100]; built.media.size = [390,610];
      built.previous_media.pos = [500,1430]; built.previous_media.size = [390,610];
      built.prompt.pos = [960,760]; built.prompt.size = [390,300];
      built.save.pos = [3260,80]; built.save.size = [430,520];
      const note = LiteGraph.createNode('MarkdownNote');
      g.add(note); note.pos=[960,1160]; note.size=[900,400];
      note.widgets[0].value = `# H3 模块实验 · ${spec.variant === 'film' ? 'Film 固定 2×' : '3D / LMS'}\n\n`+
        '双击任一子图查看真实节点。参数、模型、时长、源视频、上下文、首采、超分、二采、修脸、裁切调色均已展开。\n\n'+
        '**从 00 参数开始**：默认 5 秒、二采开启，上下文和修脸关闭；当前素材全部可留空。上一段成片只填其第一个视频，且必须打开上下文开关。\n\n'+
        '**超分实验**：双击 05。3D 版可以直接切换原版 / LMS 权重；Film 版将加噪和 DisableNoise 成套输出，不能单独改回 RandomNoise。\n\n'+
        '**尺寸**：目标宽高自动按 64 对齐，首采取一半。两版默认 1344×768。源视频普通分段使用 24fps 视频。\n\n'+
        '复刻模式以第一个源视频决定时长，普通模式使用填写时长。输出只含本段；22 帧上下文和帧格余量自动裁掉。\n\n'+
        '关闭的分支通过 lazy ifElse 跳过。未执行 GPU 质量 / 速度对比；请先用短片实验。';
      g.extra = {...g.extra, h3_modular:{variant:spec.variant, fps:24, context_frames:22, default_first_pass_scale:0.5},
        ds:{scale:0.7,offset:[180,200]}};
      app.canvas.ds.scale=0.7; app.canvas.ds.offset=[180,200];
      app.canvas.setDirty(true,true);
      const workflow = g.serialize();
      for (const s of workflow.definitions.subgraphs) {
        const left=Math.min(...s.nodes.map(n=>n.pos[0]))-320;
        const right=Math.max(...s.nodes.map(n=>n.pos[0]+n.size[0]))+180;
        const top=Math.min(...s.nodes.map(n=>n.pos[1]));
        s.inputNode.bounding=[left,top,260,Math.max(120,s.inputs.length*20+48)];
        s.outputNode.bounding=[right,top,260,Math.max(120,s.outputs.length*20+48)];
        s.inputs.forEach((p,i)=>{p.pos=[left+236,top+24+i*20];});
        s.outputs.forEach((p,i)=>{p.pos=[right+24,top+24+i*20];});
      }
      // Both versions expose the same super-resolution preparation interface.
      const high = workflow.definitions.subgraphs.find(s => s.name.startsWith('05'));
      const host = workflow.nodes.find(n => n.type === high.id);
      const names = ['clip','vae','audio_vae','image','video','width','height','length','source_frames','use_source_guide',
        'context_frames','context_audio','enable_context','seed','latent','model'];
      if (high.inputs.length !== names.length) throw new Error('Unexpected upscale interface');
      for (let i=0;i<names.length;i++) {
        high.inputs[i].name=names[i]; host.inputs[i].name=names[i];
        if (host.inputs[i].widget) host.inputs[i].widget.name=names[i];
      }
      const order=['LATENT','NOISE','SIGMAS','GUIDER'];
      const oldOutputs=[...high.outputs], oldHostOutputs=[...host.outputs];
      high.outputs=order.map(type=>oldOutputs.find(o=>o.type===type));
      host.outputs=order.map(type=>oldHostOutputs.find(o=>o.type===type));
      const remap=oldOutputs.map(o=>order.indexOf(o.type));
      for (const link of high.links) if (link.target_id===-20) link.target_slot=remap[link.target_slot];
      for (const link of workflow.links) if (link[1]===host.id) link[2]=remap[link[2]];
      for (let i=0;i<order.length;i++) {
        const name=['latent','noise','sigmas','guider'][i];
        high.outputs[i].name=name; host.outputs[i].name=name;
      }
      // Reload the exact artifact before exporting its real executable prompt.
      await app.loadGraphData(workflow);
      const prompt = await app.graphToPrompt();
      const ids = {}, runtimeNodes = {};
      const visit = (graph, prefix='') => {
        for (const n of graph._nodes) {
          const id = prefix+n.id;
          if (n.isSubgraphNode()) visit(n.subgraph, id+':');
          else if (n.properties.h3_modular_key) {
            ids[id]=n.properties.h3_modular_key;
            runtimeNodes[n.properties.h3_modular_key]={id,node:n};
          }
        }
      };
      visit(app.graph);
      // Check the actual graphToPrompt result after native clone/reload, not just JSON links.
      for (const item of spec.nodes) {
        const runtime=runtimeNodes[item.key];
        const api=prompt.output[runtime.id];
        if (api.class_type!==item.type) throw new Error(`Wrong class for ${item.key}`);
        for (let [name,expected] of Object.entries(item.values)) {
          if (name==='#0') name=runtime.node.inputs[0].name;
          let actual=api.inputs[name];
          if (Array.isArray(actual)) actual=[ids[actual[0]],actual[1]];
          if (JSON.stringify(actual)!==JSON.stringify(expected)) {
            throw new Error(`Exported input mismatch ${item.key}.${name}: ${JSON.stringify(actual)}`);
          }
        }
        const schema=runtime.node.constructor.nodeData.input;
        const checkInputs = definitions => {
          for (const [name,definition] of Object.entries(definitions??{})) {
            const [type,options={}]=definition;
            const value=api.inputs[name];
            if (type==='COMFY_AUTOGROW_V3') {
              if (!Object.keys(api.inputs).some(k=>k.startsWith(name+'.'))) throw new Error(`Missing ${item.key}.${name}`);
              continue;
            }
            if (value===undefined) throw new Error(`Missing ${item.key}.${name}`);
            if (Array.isArray(value)) {
              const upstream=prompt.output[value[0]];
              if (!upstream) throw new Error(`Dangling input ${item.key}.${name}`);
              continue;
            }
            const choices=Array.isArray(type)?type:options.options;
            if (type==='COMFY_DYNAMICCOMBO_V3') {
              const chosen=choices.find(c=>c.key===value);
              if (!chosen) throw new Error(`Invalid mode ${item.key}.${name}`);
              const nested=Object.fromEntries(Object.entries(chosen.inputs?.required??{}).map(([k,v])=>[name+'.'+k,v]));
              checkInputs(nested);
            } else if (choices && !choices.includes(value)) throw new Error(`Invalid choice ${item.key}.${name}: ${value}`);
          }
        };
        checkInputs(schema.required);
      }
      const params=app.graph._nodes.find(n=>n.title.startsWith('00'));
      const durationWidget=params.widgets.find(w=>w.name.startsWith('成片时长'));
      durationWidget.value=7.5;
      const edited=await app.graphToPrompt();
      if (edited.output[runtimeNodes.duration.id].inputs.value!==7.5) throw new Error('Promoted duration is not editable');
      durationWidget.value=5;
      return {workflow, flat, prompt, counts:{root:g._nodes.length, subgraphs:workflow.definitions?.subgraphs?.length, flat:flat.nodes.length}};
    }, spec);
    const name = `H3_模块实验_${spec.variant === 'film' ? 'Film2x' : '3D-LMS'}`;
    results.push({name, ...result.counts, workflow:result.workflow, flat:result.flat, prompt:result.prompt.output});
  }
  return results;
}
